FROM sales |> WHERE NOT (region = 'west' AND t >= TIMESTAMP '2024-03-01' AND t < TIMESTAMP '2024-05-01') |> AGGREGATE sum(units) AS units GROUP BY date_trunc('month', t) AS month, region |> CALL impute(month, [region], units, value => 0, flag => imputed) |> AGGREGATE line(x => month, y => units, color => region, orient => 'vertical') AS line
